local Compass = {}
local PRODUCTS = {
    compass = { name = "Kompas", ironCost = 2, time = 3, cost = 50, accuracy = 0.60, description = "Magnetni kompas." },
    astrolabe = { name = "Astrolab", ironCost = 3, brassCost = 1, time = 7, cost = 200, accuracy = 0.80, prestige = 5, description = "Za astronomske meritve." },
    sextant = { name = "Sekstant", ironCost = 4, brassCost = 2, glassCost = 1, time = 14, cost = 500, accuracy = 0.90, prestige = 10, description = "Napredna navigacijska naprava." },
    star_chart = { name = "Zvezdna karta", parchmentCost = 3, inkCost = 2, time = 10, cost = 150, accuracy = 0.70, knowledge = 15, description = "Karta zvezd." },
    portolan = { name = "Portolan", parchmentCost = 5, inkCost = 3, time = 14, cost = 300, accuracy = 0.75, prestige = 5, description = "Navigacijska karta." },
    lodestone = { name = "Magnet", ironCost = 5, time = 5, cost = 100, accuracy = 0.50, description = "Naravni magnet za kompas." },
}
local BUILDINGS = {
    workshop = { name = "Navigacijska delavnica", cost = { gold = 300, wood = 100, iron = 50 }, upkeep = 10, qualityBonus = 5 },
    observatory = { name = "Observatorij", cost = { gold = 2000, wood = 200, stone = 500 }, upkeep = 40, qualityBonus = 20, prestigeBonus = 10 },
    cartography_room = { name = "Kartografska soba", cost = { gold = 1000, wood = 200, stone = 300 }, upkeep = 25, qualityBonus = 15 },
    royal_navigational = { name = "Kraljevski navigacijski inštitut", cost = { gold = 5000, wood = 400, stone = 1000, iron = 100 }, upkeep = 100, qualityBonus = 35, prestigeBonus = 20 },
}
Compass.ironStock = 10; Compass.brassStock = 5; Compass.glassStock = 5; Compass.parchmentStock = 8; Compass.inkStock = 6
Compass.productStock = {}; Compass.buildings = {}; Compass.maker = nil; Compass.activeMaking = {}; Compass.totalProducts = 0; Compass.dayTimer = 0
function Compass.init() Compass.ironStock=10; Compass.brassStock=5; Compass.glassStock=5; Compass.parchmentStock=8; Compass.inkStock=6; Compass.productStock={}; Compass.buildings={}; Compass.maker=nil; Compass.activeMaking={}; Compass.totalProducts=0; Compass.dayTimer=0; print("[Compass] Royal Compass & Navigation Maker System initialized (6 products, 4 buildings)") end
function Compass.hireMaker(n,s) s=s or math.random(40,85); local c=400+s*8; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Compass.maker={name=n or ("Navigar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navigar najet: %s (spretnost: %d)",Compass.maker.name,s),"success") end; return true end
function Compass.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Compass.build(id) local ok,e=Compass.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Compass.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Compass.getQualityBonus() local b=0; for _,bd in ipairs(Compass.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Compass.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and Compass.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and Compass.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.glassCost and Compass.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.parchmentCost and Compass.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.inkCost and Compass.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if #Compass.buildings==0 then return false,"Potrebna delavnica" end; if not Compass.maker then return false,"Potreben navigar" end; return true end
function Compass.make(pt) local ok,e=Compass.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then Compass.ironStock=Compass.ironStock-d.ironCost end; if d.brassCost then Compass.brassStock=Compass.brassStock-d.brassCost end; if d.glassCost then Compass.glassStock=Compass.glassStock-d.glassCost end; if d.parchmentCost then Compass.parchmentStock=Compass.parchmentStock-d.parchmentCost end; if d.inkCost then Compass.inkStock=Compass.inkStock-d.inkCost end; local t=d.time; if Compass.maker then t=math.max(1,t-math.floor(Compass.maker.skill/12)) end; table.insert(Compass.activeMaking,{id="nav_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,accuracy=d.accuracy or 0,prestige=d.prestige or 0,knowledge=d.knowledge or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function Compass.completeMaking(m) local q=1.0+(Compass.getQualityBonus()/100); if Compass.maker then q=q+(Compass.maker.skill/200) end; q=math.min(2.0,q); Compass.productStock[m.productType]=(Compass.productStock[m.productType] or 0)+1; Compass.totalProducts=Compass.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if Compass.maker then Compass.maker.itemsMade=Compass.maker.itemsMade+1; if math.random()<0.15 then Compass.maker.skill=math.min(100,Compass.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navigacijska naprava izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Compass.update(dt) if not _G.state then return end; Compass.dayTimer=Compass.dayTimer+dt; if Compass.dayTimer>=30 then Compass.dayTimer=0; for i=#Compass.activeMaking,1,-1 do local m=Compass.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Compass.completeMaking(m); table.remove(Compass.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Compass.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Compass.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Compass.getStats() return {ironStock=Compass.ironStock,brassStock=Compass.brassStock,glassStock=Compass.glassStock,productStock=Compass.productStock,numBuildings=#Compass.buildings,hasMaker=Compass.maker~=nil,makerName=Compass.maker and Compass.maker.name or "—",makerSkill=Compass.maker and Compass.maker.skill or 0,activeMaking=#Compass.activeMaking,totalProducts=Compass.totalProducts} end
return Compass
